function toBool(v: any): boolean {
  if (typeof v === "boolean") return v;
  if (typeof v === "number") return v !== 0;
  if (typeof v === "string") {
    const s = v.trim().toLowerCase();
    return ["true", "t", "1", "y", "yes", "o", "○", "◯", "●", "v", "✓", "✔", "해당"].includes(s);
  }
  return false;
}

function toNumber(v: any, fallback = 0): number {
  if (v === undefined || v === null || v === "") return fallback;
  if (typeof v === "number") return Number.isFinite(v) ? v : fallback;
  const cleaned = String(v).replace(/[^0-9.-]/g, "");
  const parsed = parseFloat(cleaned);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function toIntFromAny(v: any, fallback = 0): number {
  if (v === undefined || v === null || v === "") return fallback;
  if (typeof v === "number" && Number.isFinite(v)) return Math.round(v);
  const match = String(v).match(/\d+/);
  return match ? parseInt(match[0], 10) : fallback;
}

export function normalizeMathCategory(rawCat: any): string {
  const s = String(rawCat ?? "").trim();
  if (!s) return "수와 연산";
  if (s.includes("도형")) return "도형";
  if (s.includes("측정")) return "측정";
  if (s.includes("확률") || s.includes("통계") || s.includes("자료") || s.includes("가능성") || s.includes("확·통")) {
    return "확률과 통계";
  }
  if (s.includes("규칙") || s.includes("논리") || s.includes("패턴")) {
    return s === "규칙성" ? "규칙성" : "규칙과 논리";
  }
  if (s.includes("수") || s.includes("연산") || s.includes("계산") || s.includes("방정식") || s.includes("문자") || s.includes("함수")) {
    return "수와 연산";
  }
  return s;
}

export function normalizeStandardMetaRow(raw: any, indexFallback = 1): NormalizedStandardMeta {
  const qNum = toIntFromAny(
    raw?.question_number ?? raw?.q_num ?? raw?.question_no ?? raw?.no ?? raw?.문항번호,
    indexFallback
  );
  const assignedScore = toNumber(
    raw?.assigned_score ?? raw?.score ?? raw?.max_score ?? raw?.point ?? raw?.배점,
    0
  );
  const diffRaw = toIntFromAny(
    raw?.difficulty_level ?? raw?.difficulty ?? raw?.level ?? raw?.lv ?? raw?.난이도,
    3
  );
  const difficultyLevel = Math.min(5, Math.max(1, diffRaw || 3));
  const mathCategory = normalizeMathCategory(
    raw?.math_category ?? raw?.category ?? raw?.domain ?? raw?.area ?? raw?.수학영역 ?? raw?.영역
  );

  const isCalcSense = toBool(
    raw?.is_calc_sense ?? raw?.calc_sense ?? raw?.sense ?? raw?.["수감각"] ?? raw?.["수 감각"] ?? raw?.["연산감각"]
  );
  const isSpatial = toBool(
    raw?.is_spatial_perception ??
      raw?.spatial_perception ??
      raw?.is_spatial_percep ??
      raw?.spatial_percep ??
      raw?.spatial ??
      raw?.space ??
      raw?.["공간지각력"] ??
      raw?.["공간지각"]
  );
  const isLogic = toBool(
    raw?.is_logical_reasoning ??
      raw?.logical_reasoning ??
      raw?.is_logical_reason ??
      raw?.logical_reason ??
      raw?.logic ??
      raw?.["논리추론"] ??
      raw?.["논리추론력"]
  );
  const isKnowledge = toBool(
    raw?.is_background_knowledge ??
      raw?.background_knowledge ??
      raw?.is_knowledge ??
      raw?.knowledge ??
      raw?.["배경지식"]
  );
  const isThinking = toBool(
    raw?.is_thinking_ability ??
      raw?.thinking_ability ??
      raw?.is_thinking ??
      raw?.thinking ??
      raw?.["사고력"]
  );
  const isPersistence = toBool(
    raw?.is_task_persistence ??
      raw?.task_persistence ??
      raw?.is_persistence ??
      raw?.persistence ??
      raw?.["과제집착력"]
  );

  return {
    ...raw,
    question_number: qNum,
    assigned_score: assignedScore,
    difficulty_level: difficultyLevel,
    math_category: mathCategory,
    is_calc_sense: isCalcSense,
    is_spatial_perception: isSpatial,
    is_logical_reasoning: isLogic,
    is_background_knowledge: isKnowledge,
    is_thinking_ability: isThinking,
    is_task_persistence: isPersistence,
    calc_sense: isCalcSense,
    spatial_perception: isSpatial,
    logical_reasoning: isLogic,
    background_knowledge: isKnowledge,
    thinking_ability: isThinking,
    task_persistence: isPersistence,
  };
}

/**
 * 🌟 문항 메타(admission_standard_meta_2610)의 실제 배점 합계를 최우선으로 사용하여
 * baseline 테이블의 컬럼 밀림(max_knowledge / max_thinking / max_persistence 순서 밀림) 오류를 완벽히 방지합니다.
 */
export function buildAdmissionBaseline(
  metaRows: NormalizedStandardMeta[],
  rawBaselineRow?: any
): NormalizedStandardBaseline {
  const fromMeta: NormalizedStandardBaseline = {
    max_geometry: 0,
    max_measure: 0,
    max_stat: 0,
    max_rule: 0,
    max_calc: 0,
    max_calc_sense: 0,
    max_spatial: 0,
    max_logic: 0,
    max_knowledge: 0,
    max_thinking: 0,
    max_persistence: 0,
    max_diff_1: 0,
    max_diff_2: 0,
    max_diff_3: 0,
    max_diff_4: 0,
    max_diff_5: 0,
    max_total_score: 0,
  };

  metaRows.forEach((m) => {
    const s = toNumber(m.assigned_score, 0);
    fromMeta.max_total_score += s;

    if (m.math_category === "도형") fromMeta.max_geometry += s;
    else if (m.math_category === "측정") fromMeta.max_measure += s;
    else if (m.math_category === "확률과 통계") fromMeta.max_stat += s;
    else if (m.math_category === "규칙과 논리" || m.math_category === "규칙성") fromMeta.max_rule += s;
    else if (m.math_category === "수와 연산") fromMeta.max_calc += s;

    if (m.is_calc_sense) fromMeta.max_calc_sense += s;
    if (m.is_spatial_perception) fromMeta.max_spatial += s;
    if (m.is_logical_reasoning) fromMeta.max_logic += s;
    if (m.is_background_knowledge) fromMeta.max_knowledge += s;
    if (m.is_thinking_ability) fromMeta.max_thinking += s;
    if (m.is_task_persistence) fromMeta.max_persistence += s;

    const d = m.difficulty_level;
    if (d === 1) fromMeta.max_diff_1 += s;
    else if (d === 2) fromMeta.max_diff_2 += s;
    else if (d === 3) fromMeta.max_diff_3 += s;
    else if (d === 4) fromMeta.max_diff_4 += s;
    else if (d === 5) fromMeta.max_diff_5 += s;
  });

  (Object.keys(fromMeta) as (keyof NormalizedStandardBaseline)[]).forEach((k) => {
    fromMeta[k] = Math.round((fromMeta[k] + Number.EPSILON) * 10) / 10;
  });

  // metaRows가 정상 로드되어 총점이 산출된 경우, metaRows 합계가 가장 정확하므로 그대로 반환
  if (metaRows.length > 0 && fromMeta.max_total_score > 0) {
    return fromMeta;
  }

  if (!rawBaselineRow) {
    return fromMeta;
  }

  const pickBaselineVal = (keys: string[], metaFallback: number): number => {
    for (const k of keys) {
      if (rawBaselineRow[k] !== undefined && rawBaselineRow[k] !== null && rawBaselineRow[k] !== "") {
        const num = toNumber(rawBaselineRow[k], NaN);
        if (Number.isFinite(num) && num > 0) {
          return Math.round((num + Number.EPSILON) * 10) / 10;
        }
      }
    }
    return metaFallback;
  };

  return {
    max_geometry: pickBaselineVal(["max_geometry", "geometry", "score_geometry", "geo", "도형"], fromMeta.max_geometry),
    max_measure: pickBaselineVal(["max_measure", "measure", "score_measure", "mea", "측정"], fromMeta.max_measure),
    max_stat: pickBaselineVal(["max_stat", "stat", "score_stat", "확률과 통계", "확률과통계", "확·통"], fromMeta.max_stat),
    max_rule: pickBaselineVal(["max_rule", "rule", "score_rule", "규칙과 논리", "규칙성", "규칙"], fromMeta.max_rule),
    max_calc: pickBaselineVal(["max_calc", "calc", "score_calc", "수와 연산", "수와연산", "수·연"], fromMeta.max_calc),
    max_calc_sense: pickBaselineVal(["max_calc_sense", "calc_sense", "is_calc_sense", "score_calc_sense", "sense", "수감각", "수 감각"], fromMeta.max_calc_sense),
    max_spatial: pickBaselineVal(["max_spatial", "max_spatial_percep", "max_spatial_perception", "spatial_perception", "spatial_percep", "spatial", "space", "score_spatial_percep", "공간지각력"], fromMeta.max_spatial),
    max_logic: pickBaselineVal(["max_logic", "max_logical_reason", "max_logical_reasoning", "logical_reasoning", "logical_reason", "logic", "score_logical_reason", "논리추론"], fromMeta.max_logic),
    max_knowledge: pickBaselineVal(["max_knowledge", "max_background_knowledge", "background_knowledge", "knowledge", "score_knowledge", "배경지식"], fromMeta.max_knowledge),
    max_thinking: pickBaselineVal(["max_thinking", "max_thinking_ability", "thinking_ability", "thinking", "score_thinking", "사고력"], fromMeta.max_thinking),
    max_persistence: pickBaselineVal(["max_persistence", "max_task_persistence", "task_persistence", "persistence", "score_persistence", "과제집착력"], fromMeta.max_persistence),
    max_diff_1: pickBaselineVal(["max_diff_1", "diff_1", "lv1", "level_1", "score_diff_1", "l1"], fromMeta.max_diff_1),
    max_diff_2: pickBaselineVal(["max_diff_2", "diff_2", "lv2", "level_2", "score_diff_2", "l2"], fromMeta.max_diff_2),
    max_diff_3: pickBaselineVal(["max_diff_3", "diff_3", "lv3", "level_3", "score_diff_3", "l3"], fromMeta.max_diff_3),
    max_diff_4: pickBaselineVal(["max_diff_4", "diff_4", "lv4", "level_4", "score_diff_4", "l4"], fromMeta.max_diff_4),
    max_diff_5: pickBaselineVal(["max_diff_5", "diff_5", "lv5", "level_5", "score_diff_5", "l5"], fromMeta.max_diff_5),
    max_total_score: pickBaselineVal(["max_total_score", "total_score", "total", "총점", "만점"], fromMeta.max_total_score || 100),
  };
}

/**
 * 🌟 과거 균등배점(3.33점)으로 채점된 답안이더라도 현재 기준표(admission_standard_meta_2610)의
 * 문항별 차등 배점(2점/3점/4점/5점)에 맞춰 정확한 획득 점수를 산출합니다.
 */
export function computeItemEarnedByStandard(
  ans: any,
  subScore: number,
  rawItemAssignedScore?: any,
  gcMap?: Record<string, any>,
  isAdmission = true
): { earned: number; isFullCorrect: boolean } {
  if (!ans) return { earned: 0, isFullCorrect: false };

  const code = String(ans.grading_code ?? "").trim();
  if (code) {
    let ratio = 0;
    const meta = gcMap ? gcMap[code] : null;
    if (meta) {
      if (isAdmission) {
        if (meta.admission_ratio !== undefined && meta.admission_ratio !== null) {
          ratio = Number(meta.admission_ratio) || 0;
          if (ratio > 1) ratio /= 100;
        } else if (["O", "TO", "a", "b", "c"].includes(code)) {
          ratio = 1.0;
        } else if (code === "RO") {
          ratio = 0.8;
        } else if (code === "q") {
          ratio = 0.0;
        } else {
          ratio = Number(meta.score_ratio) || 0;
          if (ratio > 1) ratio /= 100;
        }
      } else {
        ratio = Number(meta.score_ratio) || 0;
        if (ratio > 1) ratio /= 100;
      }
    } else {
      if (["O", "a", "b", "c"].includes(code)) ratio = 1.0;
      else if (code === "TO") ratio = isAdmission ? 1.0 : 0.8;
      else if (code === "RO") ratio = 0.8;
      else if (code === "q") ratio = isAdmission ? 0.0 : 0.5;
      else ratio = 0.0;
    }

    const earned = Math.round((subScore * ratio + Number.EPSILON) * 1000) / 1000;
    const isFullCorrect = ratio >= 0.99 || ["O", "TO", "a", "b", "c"].includes(code);
    return { earned, isFullCorrect };
  }

  const isCor = ans.is_correct === true || String(ans.is_correct).toLowerCase() === "true";
  if (isCor) {
    return { earned: subScore, isFullCorrect: true };
  }

  const rawEarned = parseFloat(ans.earned_score) || 0;
  if (rawEarned > 0) {
    const oldBase = parseFloat(rawItemAssignedScore) || 100 / 30;
    // 만약 기존에 만점(예: 3.333점 또는 1.667점)을 받았던 문항이면 새 배점에서도 만점 부여
    if (Math.abs(rawEarned - oldBase) < 0.08 || Math.abs(rawEarned - subScore) < 0.08) {
      return { earned: subScore, isFullCorrect: true };
    }
    const ratio = oldBase > 0 ? Math.min(1, rawEarned / oldBase) : 0;
    const earned = Math.round((subScore * ratio + Number.EPSILON) * 1000) / 1000;
    return { earned, isFullCorrect: ratio >= 0.99 };
  }

  return { earned: 0, isFullCorrect: false };
}

export async function loadAdmissionStandardData(supabaseClient: any, standardName: string) {
  const rawStd = String(standardName || "").trim();
  const matchTag = rawStd.match(/\d+-\d+/);
  const coreTag = matchTag ? matchTag[0] : rawStd;

  let rawMetaRows: any[] = [];
  let rawBaselineRow: any = null;

  // 1. 서버 액션(Service Role Key)으로 먼저 조회하여 RLS 차단 및 표기 차이 해결
  try {
    const serverRes = await fetchAdmissionStandardDataAction(rawStd);
    if (serverRes && serverRes.success) {
      rawMetaRows = serverRes.metaRows || [];
      rawBaselineRow = serverRes.baselineRow || null;
    }
  } catch (e) {
    // 서버 액션 실패 시 클라이언트 쿼리로 폴백
  }

  // 2. 클라이언트 쿼리 폴백 (서버 액션 결과 없을 때)
  if ((!rawMetaRows || rawMetaRows.length === 0) && supabaseClient) {
    try {
      const { data: m2610 } = await supabaseClient
        .from("admission_standard_meta_2610")
        .select("*")
        .eq("standard_name", coreTag);
      if (Array.isArray(m2610) && m2610.length > 0) {
        rawMetaRows = m2610;
      } else {
        const { data: mAll2610 } = await supabaseClient.from("admission_standard_meta_2610").select("*");
        if (Array.isArray(mAll2610) && mAll2610.length > 0) {
          rawMetaRows = mAll2610.filter((r: any) =>
            String(r.standard_name ?? r.standard ?? "").includes(coreTag)
          );
        }
      }
      if (!rawMetaRows || rawMetaRows.length === 0) {
        const { data: mLegacy } = await supabaseClient
          .from("admission_standard_meta")
          .select("*")
          .eq("standard_name", coreTag);
        if (Array.isArray(mLegacy) && mLegacy.length > 0) {
          rawMetaRows = mLegacy;
        }
      }
    } catch (e) {}
  }

  // 3. 내장 2610 기준표 폴백 (RLS 설정이나 환경변수 누락으로 DB 조회가 빈 배열일 때도 100% 정상 작동 보장)
  if (!rawMetaRows || rawMetaRows.length === 0) {
    rawMetaRows = FALLBACK_META_2610.filter(
      (r) => r.standard_name === coreTag || r.standard_name === rawStd
    );
  }

  // 4. 정규화 및 배점 보정
  const normalizedMeta: NormalizedStandardMeta[] = (rawMetaRows || [])
    .map((r: any, idx: number) => normalizeStandardMetaRow(r, idx + 1))
    .sort((a, b) => a.question_number - b.question_number);

  const defaultScorePerQ = normalizedMeta.length > 0 ? 100 / normalizedMeta.length : 100 / 30;
  const totalMetaScore = normalizedMeta.reduce((acc, m) => acc + (Number(m.assigned_score) || 0), 0);
  if (normalizedMeta.length > 0 && totalMetaScore <= 0) {
    normalizedMeta.forEach((m) => {
      m.assigned_score = defaultScorePerQ;
    });
  } else {
    normalizedMeta.forEach((m) => {
      if (!m.assigned_score || m.assigned_score <= 0) {
        m.assigned_score = defaultScorePerQ;
      }
    });
  }

  const mData: { [qNum: number]: NormalizedStandardMeta } = {};
  const metaScores: { [qNum: number]: number } = {};
  normalizedMeta.forEach((m, idx) => {
    const qn = m.question_number || idx + 1;
    mData[qn] = m;
    metaScores[qn] = m.assigned_score;
  });

  const rBase = buildAdmissionBaseline(normalizedMeta, rawBaselineRow);

  return {
    meta: normalizedMeta,
    mData,
    metaScores,
    baselineRow: rawBaselineRow,
    rBase,
  };
}
